'use server';
/**
 * @fileOverview An AI agent for diagnosing plant health from images.
 *
 * - plantImageDiagnosis - A function that handles the plant image diagnosis process.
 * - PlantImageDiagnosisInput - The input type for the plantImageDiagnosis function.
 * - PlantImageDiagnosisOutput - The return type for the plantImageDiagnosis function.
 */

import { ai } from '@/ai/genkit';
import { z } from 'genkit';

const PlantImageDiagnosisInputSchema = z.object({
  photoDataUri: z
    .string()
    .describe(
      "A photo of a plant, as a data URI that must include a MIME type and use Base64 encoding. Expected format: 'data:<mimetype>;base64,<encoded_data>'."
    ),
  description: z
    .string()
    .optional()
    .describe('An optional description of the plant or observed symptoms.'),
});
export type PlantImageDiagnosisInput = z.infer<typeof PlantImageDiagnosisInputSchema>;

const PlantImageDiagnosisOutputSchema = z.object({
  isHealthy: z.boolean().describe('Whether the plant appears to be healthy.'),
  diagnosisSummary: z.string().describe('A concise summary of the plant\'s health diagnosis.'),
  potentialIssues: z
    .array(z.string())
    .describe('A list of potential issues or diseases identified.'),
  recommendations: z
    .array(z.string())
    .describe('Actionable recommendations to address the identified issues or maintain health.'),
});
export type PlantImageDiagnosisOutput = z.infer<typeof PlantImageDiagnosisOutputSchema>;

export async function plantImageDiagnosis(
  input: PlantImageDiagnosisInput
): Promise<PlantImageDiagnosisOutput> {
  return plantImageDiagnosisFlow(input);
}

const plantImageDiagnosisPrompt = ai.definePrompt({
  name: 'plantImageDiagnosisPrompt',
  input: { schema: PlantImageDiagnosisInputSchema },
  output: { schema: PlantImageDiagnosisOutputSchema },
  prompt: `You are an expert botanist and plant health diagnostician. Your task is to analyze the provided image and description of a plant to determine its health status and identify any potential issues.

Based on the visual evidence from the photo and any additional description, provide a diagnosis.

If the plant is healthy, state that it is healthy and provide general care tips. If there are issues, clearly state them and offer practical recommendations for treatment or improvement.

Input:
Description: {{{description}}}
Photo: {{media url=photoDataUri}}

Provide the output in JSON format according to the output schema.`,
});

const plantImageDiagnosisFlow = ai.defineFlow(
  {
    name: 'plantImageDiagnosisFlow',
    inputSchema: PlantImageDiagnosisInputSchema,
    outputSchema: PlantImageDiagnosisOutputSchema,
  },
  async (input) => {
    const { output } = await plantImageDiagnosisPrompt(input);
    if (!output) {
      throw new Error('Failed to get a diagnosis from the AI model.');
    }
    return output;
  }
);
